INSERT INTO task_type_template (type_id, locale, render_target, template_text, spec_version)
VALUES
    ('G7-FRA-001', 'ru-KZ', 'plaintext', 'Путь длиной {{a}}/{{b}} мили пройден за {{c}}/{{d}} часа. Найдите скорость в милях в час.', '1.0.0-draft'),
    ('G7-FRA-002', 'ru-KZ', 'plaintext', 'Зависимость задана формулой y = 4x. Является ли она прямо пропорциональной?', '1.0.0-draft'),
    ('G7-FRA-003', 'ru-KZ', 'plaintext', 'В зависимости y = kx при x = {{x}} значение y равно {{y}}. Найдите k.', '1.0.0-draft'),
    ('G7-FRA-004', 'ru-KZ', 'plaintext', 'Даны пары значений (1, 3), (2, 6), (3, 9). Является ли зависимость прямо пропорциональной?', '1.0.0-draft'),
    ('G7-DEC-001', 'ru-KZ', 'plaintext', 'Фактическое значение: {{a}}, оценочное значение: {{b}}. Найдите относительную погрешность в процентах.', '1.0.0-draft'),
    ('G7-DEC-002', 'ru-KZ', 'plaintext', 'Счёт составляет {{a}} условных единиц, чаевые — {{p}}%. Найдите сумму чаевых.', '1.0.0-draft'),
    ('G7-DEC-003', 'ru-KZ', 'plaintext', 'Вклад {{p}} условных единиц размещён под {{r}}% годовых на {{t}} лет. Найдите простые проценты.', '1.0.0-draft'),
    ('G7-DEC-004', 'ru-KZ', 'plaintext', 'Начальная цена — {{a}} условных единиц. Сначала применили скидку {{p}}%, затем налог {{q}}%. Найдите итоговую цену.', '1.0.0-draft'),
    ('G7-GEO-001', 'ru-KZ', 'plaintext', 'Масштаб чертежа — 1:{{s}}. Длина отрезка на чертеже — {{a}}. Найдите соответствующую фактическую длину.', '1.0.0-draft'),
    ('G7-GEO-002', 'ru-KZ', 'plaintext', 'Масштаб карты — 1:{{s}}. Расстояние на карте — {{a}}. Найдите соответствующее фактическое расстояние.', '1.0.0-draft'),
    ('G7-GEO-004', 'ru-KZ', 'plaintext', 'Фактическая длина — {{a}}, длина на чертеже — {{b}}. Найдите масштабный коэффициент (фактическая длина, делённая на длину на чертеже).', '1.0.0-draft'),
    ('G7-GEO-005', 'ru-KZ', 'plaintext', 'Фигура состоит из прямоугольника со сторонами {{a}} и {{b}} и полуокружности радиуса {{r}}, присоединённой по диаметру. Найдите общую площадь.', '1.0.0-draft')
